mapper.update:
update mem_purchase_return
set status='COMPLETED', refunded_amount=#{refundedAmount}, update_by=#{updateBy}, update_time=sysdate(), version=version+1
where return_id=#{returnId} and tenant_id=#{tenantId} and dept_id=#{deptId}
  and del_flag='0' and status='DRAFT' and version=#{version}

update mem_purchase_return
set customer_name=#{customerName}, customer_phone=#{customerPhone}, reason=#{reason}, remark=#{remark},
    update_by=#{updateBy}, update_time=sysdate(), version=version+1
where return_id=#{returnId} and tenant_id=#{tenantId} and dept_id=#{deptId}
  and del_flag='0' and status='DRAFT' and version=#{version}

update mem_purchase_return
set refund_amount=#{refundAmount}, update_by=#{updateBy}, update_time=sysdate(), version=version+1
where return_id=#{returnId} and tenant_id=#{tenantId} and dept_id=#{deptId}
  and del_flag='0' and status='DRAFT' and version=#{version}
